35	            --title-size: clamp(2rem, 6vw, 5rem);
36	            --subtitle-size: clamp(0.875rem, 2vw, 1.25rem);
37	            --body-size: clamp(0.75rem, 1.2vw, 1rem);
38	
39	            /* Spacing — MUST use clamp() */
40	            --slide-padding: clamp(1.5rem, 4vw, 4rem);
41	            --content-gap: clamp(1rem, 2vw, 2rem);
42	
43	            /* Animation */
44	            --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
45	            --duration-normal: 0.6s;
46	        }
47	
48	        /* ===========================================
49	           BASE STYLES
50	           =========================================== */
51	        * { margin: 0; padding: 0; box-sizing: border-box; }
52	
53	        /* --- PASTE viewport-base.css CONTENTS HERE --- */
54	
55	        /* ===========================================
56	           ANIMATIONS
57	           Trigger via .visible class (added by JS on scroll)
58	           =========================================== */
59	        .reveal {
60	            opacity: 0;
61	            transform: translateY(30px);
62	            transition: opacity var(--duration-normal) var(--ease-out-expo),
63	                        transform var(--duration-normal) var(--ease-out-expo);
64	        }
65	
66	        .slide.visible .reveal {
67	            opacity: 1;
68	            transform: translateY(0);
69	        }
