const { chromium } = require('playwright');
const http = require('http');
const fs = require('fs');
const path = require('path');

(async () => {
    const browser = await chromium.launch({
        executablePath: '/root/.cache/ms-playwright/chromium-1155/chrome-linux/chrome'
    });
    const page = await browser.newPage();
    await page.setViewportSize({ width: 1920, height: 1080 });

    // Simple HTTP server for local files
    const dir = '/app/output';
    const server = http.createServer((req, res) => {
        let filePath = path.join(dir, req.url === '/' ? 'deck.html' : req.url);
        const ext = path.extname(filePath);
        const contentTypes = {
            '.html': 'text/html',
            '.jpg': 'image/jpeg',
            '.jpeg': 'image/jpeg',
            '.png': 'image/png',
            '.css': 'text/css',
            '.js': 'application/javascript'
        };
        fs.readFile(filePath, (err, data) => {
            if (err) { res.writeHead(404); res.end(); return; }
            res.writeHead(200, { 'Content-Type': contentTypes[ext] || 'application/octet-stream' });
            res.end(data);
        });
    });
    server.listen(9877);

    await page.goto('http://127.0.0.1:9877/deck.html', { waitUntil: 'networkidle' });
    await page.waitForTimeout(1500);

    // Count slides
    const slideCount = await page.evaluate(() => document.querySelectorAll('.slide').length);
    console.log('Found slides: ' + slideCount);

    // Capture slide 1 (already visible)
    await page.screenshot({ path: '/tmp/slide_001.png', fullPage: false });
    console.log('Captured slide 1');

    // Navigate and capture remaining slides
    for (let i = 2; i <= slideCount; i++) {
        await page.keyboard.press('ArrowRight');
        await page.waitForTimeout(800);
        await page.screenshot({ path: `/tmp/slide_${String(i).padStart(3, '0')}.png`, fullPage: false });
        console.log('Captured slide ' + i);
    }

    // Verify slides are different by checking a pixel
    for (let i = 1; i <= slideCount; i++) {
        const fpath = `/tmp/slide_${String(i).padStart(3, '0')}.png`;
        const exists = fs.existsSync(fpath);
        const size = exists ? fs.statSync(fpath).size : 0;
        console.log(`Slide ${i}: ${exists ? 'exists' : 'missing'}, size: ${size}`);
    }

    await browser.close();
    server.close();
    console.log('Done capturing');
})();

