const { chromium } = require('playwright');
const http = require('http');
const fs = require('fs');
const path = require('path');

(async () => {
    const browser = await chromium.launch({
        executablePath: '/root/.cache/ms-playwright/chromium-1155/chrome-linux/chrome'
    });
    const page = await browser.newPage();
    await page.setViewportSize({ width: 1920, height: 1080 });

    // Simple HTTP server for local files
    const dir = '/app/output';
    const server = http.createServer((req, res) => {
        let filePath = path.join(dir, req.url === '/' ? 'deck.html' : req.url);
        const ext = path.extname(filePath);
        const contentTypes = {
            '.html': 'text/html',
            '.jpg': 'image/jpeg',
            '.jpeg': 'image/jpeg',
            '.png': 'image/png',
            '.css': 'text/css',
            '.js': 'application/javascript'
        };
        fs.readFile(filePath, (err, data) => {
            if (err) { res.writeHead(404); res.end(); return; }
            res.writeHead(200, { 'Content-Type': contentTypes[ext] || 'application/octet-stream' });
            res.end(data);
        });
    });
    server.listen(9878);

    await page.goto('http://127.0.0.1:9878/deck.html', { waitUntil: 'networkidle' });
    await page.waitForTimeout(1000);

    // Force all slides to be visible (triggers animations)
    await page.evaluate(() => {
        document.querySelectorAll('.slide').forEach(s => s.classList.add('visible'));
    });

    // Wait for all CSS transitions to complete (bars, reveals, etc.)
    await page.waitForTimeout(2000);

    // Count slides
    const slideCount = await page.evaluate(() => document.querySelectorAll('.slide').length);
    console.log('Found slides: ' + slideCount);

    // Verify bar widths are set (spot check)
    const barWidths = await page.evaluate(() => {
        const bars = document.querySelectorAll('.bar-fill');
        const widths = [];
        bars.forEach((bar, i) => {
            if (i < 3) widths.push({ index: i, computed: getComputedStyle(bar).width, target: bar.style.getPropertyValue('--bar-w') });
        });
        return widths;
    });
    console.log('Bar widths sample:', JSON.stringify(barWidths));

    // Screenshot each slide by scrolling to it
    for (let i = 0; i < slideCount; i++) {
        // Scroll to slide
        await page.evaluate((idx) => {
            const slides = document.querySelectorAll('.slide');
            slides[idx].scrollIntoView({ behavior: 'instant' });
        }, i);
        await page.waitForTimeout(500);
        await page.screenshot({ path: `/tmp/slide2_${String(i + 1).padStart(3, '0')}.png`, fullPage: false });
        console.log('Captured slide ' + (i + 1));
    }

    // Verify file sizes
    for (let i = 1; i <= slideCount; i++) {
        const fpath = `/tmp/slide2_${String(i).padStart(3, '0')}.png`;
        const exists = fs.existsSync(fpath);
        const size = exists ? fs.statSync(fpath).size : 0;
        console.log(`Slide ${i}: ${exists ? 'exists' : 'missing'}, size: ${size}`);
    }

    await browser.close();
    server.close();
    console.log('Done capturing');
})();

